def post(a, r):
    def uni(s, k):
        # all elements of the window a[s], ..., a[s+k-1] equal a[s]
        return And([a[s + j] == a[s] for j in range(k)])

    windows = [(s, k) for s in range(N) for k in range(1, N - s + 1)]

    # r is the length of some run of equal values
    achieved = Or([And(uni(s, k), r == k) for (s, k) in windows])

    # no run of equal values is longer than r
    maximal = And([Implies(uni(s, k), k <= r) for (s, k) in windows])

    return And(r >= 1, r <= N, achieved, maximal)
